private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int end = bb.position() + 1;  // Start of the next octet
    while (i < end) {
        byte nextOctet = bb.get();
        int charValue;
        if (nextOctet < 128) {
            charValue = nextOctet;
            sb.append((char) charValue);
        } else if (nextOctet >= 192 && nextOctet < 224) {
            charValue = (nextOctet & 0x1F) << 6;
            charValue |= (nextOctet & 0x3F);
            sb.append((char) charValue);
        } else if (nextOctet >= 224 && nextOctet < 240) {
            charValue = (nextOctet & 0x0F) << 12;
            charValue |= (nextOctet & 0x3F) << 6;
            charValue |= (nextOctet & 0x3F);
            sb.append((char) charValue);
        } else if (nextOctet >= 240 && nextOctet < 248) {
            charValue = (nextOctet & 0x07) << 18;
            charValue |= (nextOctet & 0x3F) << 12;
            charValue |= (nextOctet & 0x3F) << 6;
            charValue |= (nextOctet & 0x3F);
            sb.append((char) charValue);
        } else {
            // Invalid UTF-8 sequence
            throw new IllegalArgumentException("Invalid UTF-8 sequence");
        }
        end++;  // Move to the position after the next octet
    }
    return end;
}
