private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb.remaining() == 0) {
        return i;
    }

    int b1 = bb.get();
    if ((b1 & 0xC0) == 0xC0) {
        int b2 = bb.get();
        if ((b2 & 0xC0) != 0xC0) {
            sb.append((char) ((b1 & 0x1F) << 6) | (b2 & 0x3F));
            return i + 2;
        }
    }

    int b3 = bb.get();
    if ((b3 & 0xC0) != 0xC0) {
        sb.append((char) ((b1 & 0x1F) << 6) | (b2 & 0x3F) << 6) | (b3 & 0x3F));
        return i + 3;
    }

    int b4 = bb.get();
    if ((b4 & 0xC0) != 0xC0) {
        sb.append((char) ((b1 & 0x1F) << 6) | (b2 & 0x3F) << 6 | (b3 & 0x3F) << 6) | (b4 & 0x3F));
        return i + 4;
    }

    if ((b1 | 0xF0) == 0xF0) {
        int b2 = bb.get();
        if ((b2 | 0xF0) != 0xF0) {
            int b3 = bb.get();
            if ((b3 | 0xF0) != 0xF0) {
                int b4 = bb.get();
                if ((b4 | 0xF0) != 0xF0) {
                    sb.append((char) ((b1 & 0x0F) << 12) | (b2 & 0xFF) << 6) | (b3 & 0xFF) | (b4 & 0xFF));
                    return i + 5;
                }
            }
        }
    }

    if ((b1 | 0xF8) == 0xF8) {
        int b2 = bb.get();
        if ((b2 | 0xF8) != 0xF8) {
            int b3 = bb.get();
            if ((b3 | 0xF8) != 0xF8) {
                int b4 = bb.get();
                if ((b4 | 0xF8) != 0xF8) {
                    sb.append((char) ((b1 & 0x03) << 16) | (b2 & 0xFF) | (b3 & 0xFF) | (b4 & 0xFF) | (b5 & 0xFF));
                    return i + 6;
                }
            }
        }
    }

    throw new IllegalArgumentException("Invalid UTF-8 sequence encountered at position " + i);
}
