private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node; // No need to rotate
    }

    TreeNode<T> tempNode = node.left;
    node.left = tempNode.right;
    tempNode.right = node;
    return tempNode;
}
