    // Create the result map with vertex colors based on the target graph's colors
    Map<String, V> vertexColors = new HashMap<>();
    for (E edge : target.getEdges()) {
        vertexColors.computeIfAbsent(edge.getKey(), key -> resultMap.getOrDefault(key,graph.createVertex()));
        vertexColors.computeIfAbsent(edge.getValue(), key -> resultMap.getOrDefault(key,graph.createVertex()));
    }

    // Generate the complete bipartite graph
    for (String from : generatorOptions.getFromSet()) {
        for (String to : generatorOptions.getToSet()) {
            if (!from.equals(to)) {
                V sourceVertex = vertexColors.get(from);
                V targetVertex = vertexColors.get(to);
                target.addEdge(new Edge<>(sourceVertex, targetVertex));
            }
        }
    }
}
