public class TimeRangeBuilder {
    protected static final long FETCH_DATA_DURATION = 1000; // 1 second in milliseconds

    protected List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> ranges = new ArrayList<>();
        while (end >= start) {
            long nextEnd = Math.min(end, start + FETCH_DATA_DURATION - 1);
            ranges.add(new TimeRange(start, nextEnd));
            start = nextEnd + 1;
        }
        return ranges;
    }

    private static class TimeRange {
        private long start;
        private long end;

        public TimeRange(long start, long end) {
            this.start = start;
            this.end = end;
        }

        public long getStart() {
            return start;
        }

        public long getEnd() {
            return end;
        }
    }
}
