import org.joda.time.LocalDateTime;
import org.joda.time.Period;
import org.jetbrains.annotations.NotNull;

import java.time.LocalDateTime;
import java.time.Period;
import java.util.List;

public class DateRangeSplitter {
    private static final long FETCH_DATA_DURATION = 30 * 60 * 1000; // 30 minutes in milliseconds

    @NotNull
    public List<TimeRange> buildTimeRanges(long start, long end) {
        List<TimeRange> timeRanges = new ArrayList<>();
        LocalDateTime startDateTime = LocalDateTime.ofEpochSecond(start, 0, LocalDateTime.now().getZone());
        LocalDateTime endDateTime = LocalDateTime.ofEpochSecond(end, 0, LocalDateTime.now().getZone());

        do {
            LocalDateTime rangeStart = startDateTime.minus(Period.minutes(30));
            LocalDateTime rangeEnd = Math.min(rangeStart.plusSeconds(FETCH_DATA_DURATION), endDateTime);

            if (startDateTime.isBefore(rangeStart) || endDateTime.isAfter(rangeEnd)) {
                break;
            }

