public List<TimeRange> buildTimeRanges(final long start, final long end) {
    long diff = end - start;
    long duration = FETCH_DATA_DURATION;
    int parts = (int) (diff / duration);
    diff %= duration;
    List<TimeRange> timeRanges = new ArrayList<>(parts + 1);
    long filled = 0;
    for (int i = 0; i < parts; i++) {
        timeRanges.add(new TimeRange(start + filled, start + filled + duration));
        filled += duration;
    }
    timeRanges.add(new TimeRange(start + filled, start + filled + diff));
    return timeRanges;
