public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    int UTF8Offset = index;

    while (UTF8Offset < index + len) {
        if (str.charAt(UTF8Offset) == 0xEF) { // Byte for start of multibyte encoding
            if (UTF8Offset + 1 < index + len && str.charAt(UTF8Offset + 1) == 0xBB) { // Byte for continuation of multibyte encoding 1
                UTF8Offset += 2;
            } else if (UTF8Offset + 2 < index + len && str.charAt(UTF8Offset + 2) == 0xBF) { // Byte for continuation of multibyte encoding 2
                UTF8Offset += 3;
            } else { // Reached end of multibyte encoding
                return size;
            }
        } else {
            size++;
            UTF8Offset++;
            if (str.charAt(UTF8Offset) == 0xc0 && (UTF8Offset + 1) < index + len && str.charAt(UTF8Offset + 1) >= 0xc1) { // Byte indicating non-starting byte (continuation byte)
                return size;
            }
        }
    }

    return -1; // Error in calculation
}
