        i++;
        count++;
    }
    while (i < index + len) {
        int b = str.charAt(i++);
        if ((b & 0xF0) == 0xF0) {
            count += 3;
        } else if ((b & 0xE0) == 0xE0) {
            count += 2;
        } else if ((b & 0xC0) == 0xC0) {
            count += 1;
