        } else if (c <= 0x7FF) {
            // 11 bit UTF-8
            lb.put((byte)(0xC0 | (c >> 6)));
            lb.put((byte)(0x80 | (c & 0x3F)));
        } else if (c <= 0xFFFF) {
            // 16 bit UTF-8
