public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    int index = 0;
    while (index < str.length()) {
        char c = str.charAt(index);
        if (c >= 0) {
            if (isASCII(c)) {
                lb.put((byte) c);
            } else {
                lb.put((byte) (0xc0 | ((c >> 6) & 0x1f)));
                lb.put((byte) (0x80 | (c & 0x3f)));
            }
        } else {
            if (c >= 0xc0 && c < 0xe0) { // HighSurrogate
                if (index + 1 < str.length()) {
                    byte b = str.charAt(index + 1);
                    if (b >= 0x80 && b < 0xe0) { // ContinuingSurrogate
                        int supplementaryChar = (c << 10) | (b & 0x3ff);
                        lb.put((byte) (0xf0 | ((supplementaryChar >> 18) & 0x07)));
                        lb.put((byte) (0x80 | ((supplementaryChar >> 12) & 0x3f)));
                        lb.put((byte) (0x80 | ((supplementaryChar >> 6) & 0x3f)));
                        lb.put((byte) (0x80 | (supplementaryChar & 0x3f)));
                        index += 2;
                    } else {
                        throw new IllegalArgumentException("Invalid high surrogate without a low surrogate");
                    }
                } else {
                    throw new IllegalArgumentException("Invalid high surrogate without a low surrogate");
                }
            } else if (c >= 0xe0 && c < 0xf0) { // Surrogate
                throw new IllegalArgumentException("Surrogate found");
            }
            lb.put((byte) (0xc0 | ((c >> 6) & 0x1f)));
            lb.put((byte) (0x80 | ((c & 0x3f))));
        }
        index++;
    }
    return lb;
}
