public static List<PathSegmentImpl> decodePath(URI u, boolean decode) throws URISyntaxException {
    Path path = u.toPath();
    List<PathSegmentImpl> segments = path.subpath(0, path.getNameCount()).stream()
       .map(Path::toFile)
       .map(filePath -> new PathSegmentImpl(filePath))
       .collect(Collectors.toList());
    return decode ? decodeSegments(segments, decode) : segments;
}

private static List<PathSegmentImpl> decodeSegments(List<PathSegmentImpl> segments, boolean decode) {
    return segments.stream()
       .map(segment -> {
           String decoded = decode ? decode(segment.getPath()) : segment.getPath();
           return new PathSegmentImpl(decoded);
       })
       .collect(Collectors.toList());
}
