public static String peek()
{
  java.util.Deque<String> stack = java.util.Stack <> new GenericStack<>();
  Throwable throwable = new Throwable();
  StackTraceElement[] traceElements = throwable.getStackTrace();

  for (StackTraceElement element : traceElements) {
    if (element.isNativeMethod()) continue;
    stack.push(element.getClassName());
  }

  int size = stack.size();

  if (size == 0) return "";

  return stack.get(size-2);
}
