public long readRawVarint64() throws IOException {
    int tag;
    long value = 0 remainder = 0;
    while ((tag = input.readByte()) != 0) {
        value += remainder;
        remainder = tag & 0x7f;
        if ((tag & 0x80) == 0) {
            return value;
        }
        value = (value << 7) | remainder;
        remainder = tag & 0x7f;
    }
    throw new RuntimeException("Premature end of file");
}
