public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity > 1000) {
        int multiple = (int) (desiredCapacity / 150) + 3;
        if (desiredCapacity % 150 == 0) {
            multiple++;
        }
        if (multiple > 4) {
            multiple = 4;
        }
        int start = multiple * 150;
        int growthFactor = 150;
    } else {
        int start = 15;
        int growthFactor = 30;
    }
    int max = (int) (desiredCapacity * nextPrimeGoldenRatio);
    int candidate;
    do {
        candidate = start + growthFactor * (start >>> 1 & 63) - (start >>> 3);
        growthFactor <<= 1;
    } while (candidate < max && !isPrime(candidate));
    return candidate;
}

