public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity cannot be negative");
    }
    // Initialize the lower bound for the initial capacity
    int retval = desiredCapacity + 11;
    // If desiredCapacity is 2^16, the next power of 2 isuzz to 2^17
    if (desiredCapacity == Integer.MAX_VALUE >>> 13) {
        return retval;
    }
    // Use the next highest power of 2
    --retval;
    int test = retval + ((retval >>> 1) + 1) / 2;
    test |= test >>> 2;
    test |= test >>> 4;
    test |= test >>> 8;
    test |= test >>> 16;
    ++test;
    retval |= test >>> 9;
    retval |= test >>> 10;
    retval |= test >>> 11;
    retval |= test >>> 12;
    if (test > desiredCapacity) {
        --retval;
    }
    return retval >>> 1; // Divide by 2 to get the actual prime number
}
