public static int nextPrime(int desiredCapacity) {
    int result = 0;
    if (findNextPrime(desiredCapacity) == -1) {
        if (desiredCapacity >= 4) {
            int m = desiredCapacity + 3;
            int i = 5;
            do {
                if (m % i == 0 && isPrime(i))
                    m += 6;
                else
                    i += 2;
            } while (m <= desiredCapacity);
            result = m;
        } else if (desiredCapacity >= 2) {
            result = 2;
        } else {
            result = 1;
        }
    } else {
        result = findNextPrime(desiredCapacity);
    }
    return result;
}

private static int findNextPrime(int desiredCapacity) {
    if (desiredCapacity >= 4) {
        for (int i = 5; i <= desiredCapacity; i += 6) {
            if (isPrime(i))
                return i;
        }
        for (int i = 7; i <= desiredCapacity; i += 6) {
            if (isPrime(i))
                return i;
        }
    } else if (desiredCapacity >= 2) {
        if (desiredCapacity == 2)
            return 2;
        if (isPrime(desiredCapacity))
            return desiredCapacity;
        return 3;
    } else {
        if (isPrime(1))
            return 1;
        return 2;
    }
}

private static boolean isPrime(int value) {
    if (value <= 1)
        return false;
    if (value <= 3)
        return true;
    if (value % 2 == 0 || value % 3 == 0)
        return false;
    int i = 5;
    while (i * i <= value) {
        if (value % i == 0 || value % (i + 2) == 0)
            return false;
        i += 6;
    }
    return true;
}
