public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder unescaped = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case '\"':
                    case '\'':
                        // Double or single quotes escape the next character
                        if (i > 0 && str.charAt(i - 1) == '\\') {
                            unescaped.append(nextChar);
                            i++; // Skip the next character
                        } else {
                            unescaped.append('\\');
                            unescaped.append(nextChar);
                        }
                        break;
                    case 'n':
                        unescaped.append('\n');
                        i++; // Skip the next character
                        break;
                    default:
                        // Another escape sequence, but we don't know what it is
                        if (c == 'u') {
                            if (i + 4 < len) {
                                StringBuilder hex = new StringBuilder();
                                for (int j = i + 1; j < i + 5; j++) {
                                    hex.append(str.charAt(j));
                                }
                                int unicodeValue = Integer.parseInt(hex.toString(), 16);
                                unescaped.append((char) unicodeValue);
                                i += 4; // Skip the next four characters
                            } else {
                                throw new InvalidEscapeSequenceException("Incomplete Unicode escape sequence");
                            }
                        } else {
                            // Unrecognized escape sequence
                            throw new InvalidEscapeSequenceException("Unknown escape sequence: " + nextChar);
                        }
                        break;
                }
            } else {
                // Trailing backslash without following character
                unescaped.append('\\');
            }
        } else {
            unescaped.append(c);
        }
    }
    return unescaped.toString();
}
