        jsonString.append("\"json\":").append(this.toJsonHelper(employeeMap.get("info") != null ? (Map<String, Object>) employeeMap.get("info") : null)).append(",");
        jsonString.append("\"roles\":").append(this.toJsonHelper(employeeMap.get("roles") != null ? ( List<Object>) employeeMap.get("roles") : null)).append("}");
