    if (tag != 5) {
        throw new ClassFormatError("Unexpected tag in CONSTANT_Utf8 entry");
    }
    final int length = constantPoolBuffer.get((constantPoolEntryIndex << 2) + 1) & 0xFF;
    if (length > charBuffer.length) {
        throw new ArrayIndexOutOfBoundsException("Buffer is too small");
    }
    constantPoolBuffer.get((constantPoolEntryIndex << 2) + 2, charBuffer, 0, length);
    return new String(charBuffer, Charset.defaultCharset());
}
