private String unescapeId(String input) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                switch (nextChar) {
                    case '"':
                        c = '"';
                        break;
                    case '\\':
                        c = '\\';
                        break;
                    case 't':
                        c = '\t';
                        break;
                    case 'n':
                        c = '\n';
                        break;
                    case 'r':
                        c = '\r';
                        break;
                    default:
                        // Handle unrecognized escape sequences
                        throw new IllegalArgumentException("Unsupported escape sequence: \\/" + nextChar);
                }
                i++; // Skip the next character as it has already been processed
            } else {
                // Handle the case when the string ends with a backslash
                sb.append(c);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
