public String unescapeId(String input) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                switch (nextChar) {
                    case 'a':
                        sb.append('\u0007');
                        break;
                    case 'b':
                        sb.append('\b');
                        break;
                    case 'c':
                        sb.append('\t');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 's':
                        sb.append(' ');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'u':
                        if (i + 5 < input.length()) {
                            String unicodeCodePoint = input.substring(i + 2, i + 6);
                            sb.append((char) Integer.parseInt(unicodeCodePoint, 16));
                            i += 5; // Skip the entire encoded sequence
                        } else {
                            throw new IllegalArgumentException("Invalid Unicode escape sequence");
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Unsupported escape sequence");
                }
            } else {
                throw new IllegalArgumentException("Unexpected end of input");
            }
            i++; // Skip the next character (the escaped c)
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
