        return false;
    }
    if (node == head) {
        head = node.next;
    } else {
        ListNodeImpl<E> prev = head;
        while (prev.next != node) {
            prev = prev.next;
        }
        prev.next = node.next;
    }
    node.next = null;
    size--;
