    List<Integer> lowerBounds = new ArrayList<>();
    int currentKey = keys.get(0);
    int lowerBound = 0;
    for (int key : keys) {
        if (key > currentKey) {
            lowerKey = currentKey + 1;
            currentKey = key;
        }
