```java
public String applyRelativePath(String path, String relativePath) {
    int lastSeparatorIndex = path.lastIndexOf('/');
    if (lastSeparatorIndex != -1) {
        int relativePathIndex = relativePath.indexOf('/');
        if (relativePathIndex == -1) {
            return path + '/' + relativePath;
        } else {
            int walk = Math.min(relativePathIndex, path.length() - lastSeparatorIndex - 1);
            int i = 0;
            StringBuilder stringBuilder = new StringBuilder();
            while (i < walk) {
                stringBuilder.append(path.charAt(lastSeparatorIndex + 1 + i));
                i++;
            }
            return stringBuilder.toString() + relativePath.substring(relativePathIndex);
        }
    } else {
        return path + '/' + relativePath;
    }
}
```

