    int pos = result.indexOf("/");
    while (pos != -1 && pos < result.length() - 1) {
        if (result.charAt(pos + 1) == '/') {
            pos++;
        } else {
            result.insert(pos + 1, relativePath);
            break;
        }
    }
    return result.toString();
}
